```rust
use std::sync::atomic::{AtomicI64, Ordering};
use std::sync::Arc;
use std::thread;

fn w1(c: Arc<AtomicI64>) {
    let mut old = c.load(Ordering::SeqCst);
    loop {
        let prev = c
            .compare_exchange(old, old + 1, Ordering::SeqCst, Ordering::SeqCst)
            .unwrap_or_else(|e| e);
        if prev == old {
            return;
        }
        old = c.load(Ordering::SeqCst);
    }
}

fn w2(c: Arc<AtomicI64>) {
    let mut old = c.load(Ordering::SeqCst);
    loop {
        let prev = c
            .compare_exchange(old, old + 1, Ordering::SeqCst, Ordering::SeqCst)
            .unwrap_or_else(|e| e);
        if prev == old {
            return;
        }
        old = c.load(Ordering::SeqCst);
    }
}

fn main() {
    let c = Arc::new(AtomicI64::new(0));

    let c1 = Arc::clone(&c);
    let h1 = thread::spawn(move || w1(c1));

    let c2 = Arc::clone(&c);
    let h2 = thread::spawn(move || w2(c2));

    h1.join().unwrap();
    h2.join().unwrap();

    let done = if c.load(Ordering::SeqCst) == 2 { 1 } else { 0 };
    println!("DONE done={}", done);
}
```

